import json
import functools

def cached(func):
    """
    缓存装饰器：使用参数的 JSON 序列化（按键排序）作为缓存键，
    并限制最大缓存条目数量。
    """
    _cache = {}
    _order = []
    _maxsize = 128  # 最大缓存条目数

    @functools.wraps(func)
    def wrapper(data: dict):
        # 将字典参数序列化为稳定的 JSON 字符串作为键
        key = json.dumps(data, sort_keys=True)
        if key in _cache:
            return _cache[key]

        result = func(data)

        # 存入缓存
        _cache[key] = result
        _order.append(key)

        # 超出最大容量时移除最早的条目
        if len(_order) > _maxsize:
            oldest = _order.pop(0)
            del _cache[oldest]

        return result
    return wrapper

